    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seeds=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,1)]
    # Every solid 3x3 motif contributes its center pixel; color it by its nearest key.
